<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\Gateway;

use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\UserRoleAssignament;

class UserRoleAssignamentCursor
{
    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
    ) {
    }
    public function next(UserRoleAssignament $userRoleAssignament, ?int $size): UserRoleAssignamentCursor
    {
        $next = clone $this;
        $next->sinceUid = $userRoleAssignament->uid();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
}
